body.script:
(function(){
    function nmaUpdate(){
        var n = parseInt(document.getElementById('nma_num').value)||0;
        for(var i=1;i<=5;i++){
            var r=document.getElementById('nma_arow_'+i);
            if(r) r.style.display=i<=n?'flex':'none';
        }
    }
    window.nmaUpdate=nmaUpdate;
    window.nmaRemove=function(i){
        var r=document.getElementById('nma_arow_'+i);
        if(r) r.style.display='none';
        var s=document.getElementById('nma_num');
        if(s){var c=parseInt(s.value)||0;if(c>0){s.value=c-1;nmaUpdate();}}
    };
    var sel=document.getElementById('nma_num');
    if(sel){
        sel.addEventListener('change',nmaUpdate);
        if(sel.value){ nmaUpdate(); }
    }
})();

function nmaSwitchRes(v){
    var yesDiv = document.getElementById('nma_docs_yes');
    var noDiv  = document.getElementById('nma_docs_no');
    yesDiv.style.display = v==='yes' ? 'block' : 'none';
    noDiv.style.display  = v==='no'  ? 'block' : 'none';
    // disable inputs in hidden section so they don't submit empty
    var yesInputs = yesDiv.querySelectorAll('input[type=file]');
    var noInputs  = noDiv.querySelectorAll('input[type=file]');
    if(v==='yes'){
        yesInputs.forEach(function(i){i.disabled=false;});
        noInputs.forEach(function(i){i.disabled=true;});
    } else {
        yesInputs.forEach(function(i){i.disabled=true;});
        noInputs.forEach(function(i){i.disabled=false;});
    }
}
(function(){
    var y=document.getElementById('nma_res_yes');
    var n=document.getElementById('nma_res_no');
    if(y&&y.checked) nmaSwitchRes('yes');
    else if(n&&n.checked) nmaSwitchRes('no');
    else nmaSwitchRes('no');
})();
